import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  define: {
    'process.env.API_KEY': JSON.stringify(process.env.API_KEY),
    'process.env.VITE_GOOGLE_SCRIPT_URL': JSON.stringify(process.env.VITE_GOOGLE_SCRIPT_URL)
  }
});

export interface Exercise {
  name: string;
  sets: string;
  notes?: string;
}

export interface DailyPlan {
  day: string;
  focus: string;
  color: string;
  exercises: Exercise[];
  stretches: string[];
}

export interface WorkoutLog {
  date: string; // ISO string
  day: string;
  muscleGroup: string;
  exercise: string;
  setNumber: number;
  weight: number;
  reps: number;
  notes: string;
}

export interface WeeklyAnalysisData {
  weekNumber: number;
  muscleGroup: string;
  totalVolume: number;
  avgWeight: number;
  maxWeight: number;
  totalSets: number;
  summary: string;
}

export type Tab = 'plan' | 'log' | 'analysis' | 'history' | 'settings';

import { WorkoutLog, WeeklyAnalysisData } from '../types';

// Users will input this in the UI if not set in ENV
let SCRIPT_URL = process.env.VITE_GOOGLE_SCRIPT_URL || '';

export const setScriptUrl = (url: string) => {
  SCRIPT_URL = url;
  localStorage.setItem('gym_script_url', url);
};

export const getScriptUrl = () => {
  return SCRIPT_URL || localStorage.getItem('gym_script_url') || '';
};

export const saveWorkoutLog = async (log: WorkoutLog): Promise<boolean> => {
  const url = getScriptUrl();
  if (!url) throw new Error("Script URL not configured");

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({ action: 'logWorkout', data: log }),
    });
    const res = await response.json();
    return res.status === 'success';
  } catch (error) {
    console.error('Error saving log:', error);
    return false;
  }
};

export const getWorkoutLogs = async (): Promise<WorkoutLog[]> => {
  const url = getScriptUrl();
  if (!url) return [];

  try {
    // Append a query param to avoid caching
    const response = await fetch(`${url}?action=getLogs&t=${Date.now()}`);
    const res = await response.json();
    if (res.status === 'success') {
      return res.data;
    }
    return [];
  } catch (error) {
    console.error('Error fetching logs:', error);
    return [];
  }
};

export const saveWeeklyAnalysis = async (analysis: WeeklyAnalysisData): Promise<boolean> => {
  const url = getScriptUrl();
  if (!url) return false;

  try {
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify({ action: 'saveAnalysis', data: analysis }),
    });
    const res = await response.json();
    return res.status === 'success';
  } catch (error) {
    console.error('Error saving analysis:', error);
    return false;
  }
};

import { GoogleGenAI } from "@google/genai";
import { WorkoutLog } from "../types";

const apiKey = process.env.API_KEY || '';

export const generateWeeklyAnalysis = async (logs: WorkoutLog[]) => {
  if (!apiKey) throw new Error("API Key is missing. Check Vercel settings.");

  const ai = new GoogleGenAI({ apiKey });

  // Format logs for the prompt
  const logsText = logs.map(l => 
    `Date: ${l.date}, Muscle: ${l.muscleGroup}, Exercise: ${l.exercise}, Weight: ${l.weight}kg, Reps: ${l.reps}, Notes: ${l.notes}`
  ).join('\n');

  const prompt = `
    You are an expert fitness analyst. Analyze the following workout logs for the most recent week compared to previous data.

    Data:
    ${logsText}

    Task:
    1. Calculate total volume (weight * reps * sets) per muscle group for this week.
    2. Compare to the previous week if data exists.
    3. Identify max weight improvements.
    4. Provide a factual, numerical summary. NO motivational fluff.

    Return the response as a valid JSON object with this structure:
    {
      "summary": "String containing the text summary",
      "stats": [
        {
          "muscleGroup": "String",
          "totalVolume": Number,
          "percentChange": Number (0 if no previous data),
          "maxWeight": Number
        }
      ]
    }
    DO NOT output Markdown code blocks. Just the JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);
  } catch (error) {
    console.error("Gemini analysis failed:", error);
    throw error;
  }
};

