  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState<string | null>(null);

  const showToast = (msg: string) => {
    setToast(msg);
    setTimeout(() => setToast(null), 3000);
  };

  return (
    <div className="min-h-screen pb-20 bg-dark text-slate-100 flex flex-col">
      <header className="p-4 bg-card border-b border-slate-700 sticky top-0 z-50">
        <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-primary to-secondary">
          GymTracker AI
        </h1>
      </header>

      <main className="flex-grow p-4 overflow-y-auto">
        {activeTab === 'plan' && <PlanView onLogClick={(ex) => {
          // Pre-fill log logic would go here in a complex app
