        }} />}
        {activeTab === 'log' && <LogView setLoading={setLoading} showToast={showToast} />}
        {activeTab === 'analysis' && <AnalysisView setLoading={setLoading} />}
        {activeTab === 'history' && <HistoryView />}
        {activeTab === 'settings' && <SettingsView showToast={showToast} />}
