const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center p-2 ${active ? 'text-primary' : 'text-slate-400'}`}>
    {icon}
    <span className="text-xs mt-1">{label}</span>
  </button>
);

// --- Sub-Components ---

const PlanView = ({ onLogClick }: { onLogClick: (exercise: string) => void }) => {
  const [expandedDay, setExpandedDay] = useState<string | null>(null);

  const currentDay = new Date().toLocaleDateString('en-US', { weekday: 'long' });

  // Auto expand today
  useEffect(() => {
    setExpandedDay(currentDay);
  }, []);

  return (
    <div className="space-y-4">
      {WORKOUT_PLAN.map((plan) => (
        <div key={plan.day} className="bg-card rounded-xl overflow-hidden shadow-lg border border-slate-700">
          <button 
            onClick={() => setExpandedDay(expandedDay === plan.day ? null : plan.day)}
            className={`w-full text-left p-4 flex justify-between items-center ${expandedDay === plan.day ? plan.color : 'bg-slate-800'}`}
          >
            <div>
              <h3 className="font-bold text-lg text-white">{plan.day}</h3>
              <p className="text-sm text-white/80">{plan.focus}</p>
            </div>
            <span className="text-white text-xl">{expandedDay === plan.day ? '−' : '+'}</span>
          </button>

          {expandedDay === plan.day && (
            <div className="p-4 bg-slate-900/50">
              <h4 className="font-semibold text-primary mb-2">Exercises</h4>
              <ul className="space-y-3 mb-6">
                {plan.exercises.map((ex, i) => (
                  <li key={i} className="flex justify-between items-start border-b border-slate-700 pb-2">
                    <div>
                      <span className="block font-medium">{ex.name}</span>
                      <span className="text-sm text-slate-400">{ex.sets}</span>
                    </div>
                  </li>
                ))}
              </ul>

              <h4 className="font-semibold text-secondary mb-2">Stretches</h4>
              <ul className="list-disc list-inside text-sm text-slate-300 space-y-1">
                {plan.stretches.map((s, i) => <li key={i}>{s}</li>)}
              </ul>
            </div>
          )}
        </div>
      ))}
    </div>
  );
};

const LogView = ({ setLoading, showToast }: { setLoading: (b: boolean) => void, showToast: (s: string) => void }) => {
  const [formData, setFormData] = useState<Partial<WorkoutLog>>({
    day: new Date().toLocaleDateString('en-US', { weekday: 'long' }),
    date: new Date().toISOString().split('T')[0],
    setNumber: 1,
    weight: 0,
    reps: 0,
    exercise: '',
    muscleGroup: 'Chest'
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.exercise || !formData.weight || !formData.reps) return;

    setLoading(true);
    const success = await saveWorkoutLog(formData as WorkoutLog);
    setLoading(false);

    if (success) {
      showToast("Workout Logged!");
      setFormData(prev => ({ ...prev, setNumber: (prev.setNumber || 1) + 1 }));
    } else {
      showToast("Failed to save. Check settings.");
    }
  };

  return (
    <div className="bg-card p-6 rounded-xl border border-slate-700">
      <h2 className="text-xl font-bold mb-4 text-primary">Log Set</h2>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm text-slate-400 mb-1">Muscle Group</label>
          <select 
            className="w-full bg-dark border border-slate-600 rounded p-3 text-white"
            value={formData.muscleGroup}
            onChange={e => setFormData({...formData, muscleGroup: e.target.value})}
          >
            {MUSCLE_GROUPS.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>

        <div>
          <label className="block text-sm text-slate-400 mb-1">Exercise Name</label>
          <input 
            type="text" 
            className="w-full bg-dark border border-slate-600 rounded p-3 text-white"
            placeholder="e.g. Bench Press"
            value={formData.exercise}
            onChange={e => setFormData({...formData, exercise: e.target.value})}
            required
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm text-slate-400 mb-1">Weight (kg)</label>
            <input 
              type="number" step="0.5"
              className="w-full bg-dark border border-slate-600 rounded p-3 text-white text-lg font-mono"
              value={formData.weight || ''}
              onChange={e => setFormData({...formData, weight: parseFloat(e.target.value)})}
              required
            />
          </div>
          <div>
            <label className="block text-sm text-slate-400 mb-1">Reps</label>
            <input 
              type="number"
              className="w-full bg-dark border border-slate-600 rounded p-3 text-white text-lg font-mono"
              value={formData.reps || ''}
              onChange={e => setFormData({...formData, reps: parseFloat(e.target.value)})}
              required
            />
          </div>
        </div>

        <div className="flex justify-between items-center bg-slate-800 p-2 rounded">
            <span className="text-sm pl-2">Set #{formData.setNumber}</span>
            <button 
                type="button" 
                onClick={() => setFormData({...formData, setNumber: (formData.setNumber || 1) + 1})}
                className="text-xs text-primary px-2"
            >
                + Increment
            </button>
        </div>

        <div>
          <label className="block text-sm text-slate-400 mb-1">Notes (Optional)</label>
          <textarea 
            className="w-full bg-dark border border-slate-600 rounded p-3 text-white h-20"
            value={formData.notes || ''}
            onChange={e => setFormData({...formData, notes: e.target.value})}
          />
        </div>

        <button type="submit" className="w-full bg-primary hover:bg-blue-600 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-95">
          SAVE LOG
        </button>
      </form>
    </div>
  );
};

const AnalysisView = ({ setLoading }: { setLoading: (b: boolean) => void }) => {
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState<string>('');

  const runAnalysis = async () => {
    setLoading(true);
    setError('');
    try {
      const logs = await getWorkoutLogs();
      if (logs.length === 0) {
        setError('No logs found to analyze.');
        setLoading(false);
        return;
      }

      const result = await generateWeeklyAnalysis(logs);
      setData(result);
    } catch (e) {
      setError('Analysis failed. Check API Key or Internet.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {!data ? (
        <div className="text-center py-10">
          <p className="text-slate-400 mb-6">Generate AI insights from your logs.</p>
          <button onClick={runAnalysis} className="bg-secondary text-dark font-bold py-3 px-8 rounded-full shadow-lg hover:bg-green-400 transition-all">
            RUN WEEKLY ANALYSIS
          </button>
          {error && <p className="text-red-400 mt-4">{error}</p>}
        </div>
      ) : (
        <>
          <div className="bg-card p-4 rounded-xl border border-slate-700">
            <h3 className="text-xl font-bold text-secondary mb-2">AI Summary</h3>
            <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-line">
              {data.summary}
            </p>
          </div>

          <div className="bg-card p-4 rounded-xl border border-slate-700 h-80">
            <h3 className="text-lg font-bold text-white mb-4">Volume by Muscle Group</h3>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={data.stats}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                <XAxis dataKey="muscleGroup" stroke="#94a3b8" fontSize={12} tick={{fill: '#94a3b8'}} />
                <YAxis stroke="#94a3b8" fontSize={12} tick={{fill: '#94a3b8'}} />
                <Tooltip 
                    contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '8px' }}
                    itemStyle={{ color: '#fff' }}
                />
                <Bar dataKey="totalVolume" fill="#3b82f6" radius={[4, 4, 0, 0]} name="Total Volume (kg)" />
              </BarChart>
            </ResponsiveContainer>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {data.stats.map((stat: any, i: number) => (
                <div key={i} className="bg-slate-800 p-3 rounded-lg border border-slate-700">
                    <div className="text-xs text-slate-400">{stat.muscleGroup}</div>
                    <div className="text-lg font-bold text-white">{stat.totalVolume}kg</div>
                    <div className={`text-xs ${stat.percentChange >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                        {stat.percentChange > 0 ? '+' : ''}{stat.percentChange}%
                    </div>
                </div>
            ))}
          </div>

          <button onClick={() => setData(null)} className="w-full py-3 text-slate-400 text-sm">
            Close Analysis
          </button>
        </>
      )}
    </div>
  );
};

const HistoryView = () => {
  const [logs, setLogs] = useState<WorkoutLog[]>([]);

  useEffect(() => {
    getWorkoutLogs().then(setLogs);
  }, []);

  return (
    <div className="space-y-4">
        <h2 className="text-xl font-bold text-white mb-4">Recent Logs</h2>
        {logs.length === 0 && <p className="text-slate-500 text-center py-8">No logs found.</p>}
        {logs.map((log, i) => (
            <div key={i} className="bg-card p-4 rounded-lg border border-slate-800 flex justify-between items-center">
                <div>
                    <div className="text-xs text-primary font-bold uppercase">{log.muscleGroup}</div>
                    <div className="font-semibold text-white">{log.exercise}</div>
                    <div className="text-sm text-slate-400">{new Date(log.date).toLocaleDateString()}</div>
                </div>
                <div className="text-right">
                    <div className="text-xl font-mono font-bold text-secondary">{log.weight}kg</div>
                    <div className="text-xs text-slate-400">x {log.reps} reps</div>
                </div>
            </div>
        ))}
    </div>
  );
};

